Weighted_point wp1 = v1->point();
Weighted_point wp2 = v2->point();
Weighted_point wp3 = v3->point();

// Extract 3D coordinates and weights
double x0 = wp0.point().x(), y0 = wp0.point().y(), z0 = wp0.point().z();
double x1 = wp1.point().x(), y1 = wp1.point().y(), z1 = wp1.point().z();
double x2 = wp2.point().x(), y2 = wp2.point().y(), z2 = wp2.point().z();
double x3 = wp3.point().x(), y3 = wp3.point().y(), z3 = wp3.point().z();

double w0 = wp0.weight();
double w1 = wp1.weight();
double w2 = wp2.weight();
double w3 = wp3.weight();

// Lift to 4D: (x, y, z, w² + w) for power diagram
double lifted0[4] = { x0, y0, z0, w0 * w0 + w0 };
double lifted1[4] = { x1, y1, z1, w1 * w1 + w1 };
double lifted2[4] = { x2, y2, z2, w2 * w2 + w2 };
double lifted3[4] = { x3, y3, z3, w3 * w3 + w3 };

LiftedPoint p0(4, lifted0, lifted0 + 4);
LiftedPoint p1(4, lifted1, lifted1 + 4);
LiftedPoint p2(4, lifted2, lifted2 + 4);
LiftedPoint p3(4, lifted3, lifted3 + 4);

// Create hyperplane through the 4 lifted points
HyperPlane plane = HyperPlane(4, &p0, &p1, &p2, &p3);

// Get the coefficients (a, b, c, d) of the hyperplane: ax + by + cz + d = 0
std::vector<double> coeffs = plane.coeffs();

// The dual point of the hyperplane gives the velocity in 3D
// For hyperplane sum(a_i*x_i) + d = 0, the dual point is (-a_0/d, -a_1/d, -a_2/d)
double a = coeffs[0], b = coeffs[1], c = coeffs[2], d = coeffs[3];

// Handle near-zero denominator
if (std::abs(d) < 1e-12) {
    return Vector(0.0, 0.0, 0.0);
}

// Velocity is the direction from origin to the dual point
// Scale by time parameter
double scale = time / std::abs(d);
return Vector(-a * scale, -b * scale, -c * scale);
